companies = list_companies({})
first = list_contacts({ page: 1 })
rest = for page in list.range(2, first.total_pages + 1) {
    r = list_contacts({ page })
    return r.items
}
contacts = fold acc = first.items for chunk in rest { return acc + chunk }
domain_to_name = fold acc = {} for c in companies { return acc + { [text.lower(c.domain)]: c.name } }

processed = for c in contacts {
    phone = c.phone if c.phone != null else ""
    digits = regex.replace(phone, "[^0-9]", "")
    new_phone = if regex.test(phone, "^[+]1[0-9]{10}$") {
        return null
    } else if text.length(digits) == 10 {
        return "+1" + digits
    } else if text.length(digits) == 11 and text.starts_with(digits, "1") {
        return "+" + digits
    } else {
        return null
    }
    comp = c.company if c.company != null else ""
    email = c.email if c.email != null else ""
    parts = text.split(email, "@")
    domain = if list.length(parts) > 1 { return text.lower(parts[1]) } else { return null }
    new_company = if comp == "" and domain != null and domain in domain_to_name {
        return domain_to_name[domain]
    } else {
        return null
    }
    upd = update_contact({ id: c.id, phone: new_phone, company: new_company }) if new_phone != null or new_company != null
    return { pf: new_phone != null, cf: new_company != null }
}

phones_fixed = fold acc = 0 for row in processed { return acc + (1 if row.pf else 0) }
companies_filled = fold acc = 0 for row in processed { return acc + (1 if row.cf else 0) }
res = submit_result({ answer: { phones_fixed: phones_fixed, companies_filled: companies_filled } })
return { phones_fixed: phones_fixed, companies_filled: companies_filled, recorded: res.recorded }

